package config

// SampleConfigTemplate is a documented starter configuration generated by `tcbroker init`.
const SampleConfigTemplate = `# tcbroker configuration
# Apply with:   sudo tcbroker apply tcbroker.yaml
# Check status: tcbroker status
# Stop all:     sudo tcbroker delete --all

rules:
  # Example 1: Mirror all IPv4 ingress traffic from eth0 to eth1
  # (omitting 'filters' matches all IPv4 traffic; 'direction' defaults to 'ingress')
  - name: mirror-all
    src: eth0
    dst: eth1

  # Example 2: Filter HTTP/HTTPS traffic and mirror to multiple destinations
  - name: web-traffic
    src: eth0
    direction: ingress # ingress | egress | both
    dst:
      - eth1
      - eth2
    filters:
      - proto: tcp
        dst_port: 80
      - proto: tcp
        dst_port: 443

  # Example 3: Mirror with per-destination MAC/IP header rewrite
  # - name: forward-with-rewrite
  #   src: eth0
  #   dst:
  #     - intf: eth1
  #       rewrite:
  #         dst_mac: "52:54:00:12:34:56"
  #         dst_ip: "10.0.0.100"
  #   filters:
  #     - proto: udp
  #       src_ip: 192.168.10.0/24
  #       dst_port: 53
`
